"""Checks on synthetic data generated by a model with known parameters."""
import numpy as np
import pandas as pd

from src.data import synthetic_paris
from src.model import TemperatureModel, day_of_year_365
from src.pricing import HDDContract, hdd, mc_price, realised_hdd, simulate_season

DF = synthetic_paris(seed=1)
TRUE = TemperatureModel.paris_like()
FIT = TemperatureModel.fit(DF["date"], DF["temp"])


def test_day_of_year_has_365_days():
    d = pd.date_range("2024-01-01", "2024-12-31")
    d = d[~((d.month == 2) & (d.day == 29))]
    doy = day_of_year_365(d)
    assert doy.min() == 0 and doy.max() == 364 and len(np.unique(doy)) == 365


def test_hdd_definition():
    assert hdd([20.0, 18.0, 10.0, -2.0]) == 0 + 0 + 8 + 20


def test_parameters_are_recovered():
    # persistent AR noise makes seasonal coefficients estimated to about +/- 0.2 C on 35 years
    assert np.allclose(FIT.mean_coef[[0, 2, 3]], TRUE.mean_coef[[0, 2, 3]], atol=0.3)
    assert FIT.diagnostics["ar_order"] == 3
    assert np.allclose(FIT.phi, TRUE.phi, atol=0.03)
    assert abs(FIT.vol_coef[0] - TRUE.vol_coef[0]) < 0.2


def test_standardised_residuals_are_white_noise():
    z_acf = FIT.diagnostics["z_acf"][1:6]
    assert np.abs(z_acf).max() < 0.03


def test_call_put_parity():
    sims = simulate_season(FIT, DF, 2025, 20_000)
    k = 1450.0
    call, _ = mc_price(HDDContract(2025, k, kind="call"), sims)
    put, _ = mc_price(HDDContract(2025, k, kind="put"), sims)
    forward = 20.0 * (sims.mean() - k) * np.exp(-0.03 * 0.5)
    assert np.isclose(call - put, forward, rtol=1e-10)


def test_cap_limits_the_payout():
    pay = HDDContract(2025, 1400.0, tick=20.0, cap=1000.0).payoff(np.array([1300.0, 1420.0, 2000.0]))
    assert np.allclose(pay, [0.0, 400.0, 1000.0])


def test_forecasts_are_calibrated_under_the_true_model():
    # With the true parameters, the realised HDD should look like a draw from the forecast
    pit = [(simulate_season(TRUE, DF, s, 2000, seed=s) < realised_hdd(DF, s)).mean()
           for s in range(1992, 2025)]
    assert 0.35 < np.mean(pit) < 0.65
    inside = np.mean([(0.05 < p < 0.95) for p in pit])
    assert inside > 0.75
